(() => {
    const g = __rhf.game;
    g.state.settings.autoQuality = false;
    g.setQuality('medium');
    g.bears.directorT = 1e9;
    g.env.timeScale = 0;
    g.env.setTime(17.5);
    Object.assign(g.env.weather, { cloud: 0.3, cloudTarget: 0.3, rain: 0, rainTarget: 0, timer: 1e9 });
    g.hud.firstShown = -1000;
    g.hud.hint('', 0);
    __rhf.god(true);
    window.__until = async (fn, ms = 240000) => {
      const t0 = performance.now();
      while (performance.now() - t0 < ms) {
        const r = fn();
        if (r) return r;
        await new Promise((q) => setTimeout(q, 200));
      }
      return null;
    };
    // stand at a spot and look at a point
    window.__view = (x, z, tx, ty, tz, back = 0) => {
      const P = g.player;
      P.place(x, z, 0);
      const dx = tx - x;
      const dz = tz - z;
      P.yaw = Math.atan2(-dx, -dz);
      P.pitch = Math.atan2(ty - (P.pos.y + 1.7), Math.hypot(dx, dz));
      return 'at ' + x.toFixed(0) + ',' + z.toFixed(0) + ' y ' + P.pos.y.toFixed(1);
    };
    return 'ok';
  })()

(() => {
    const g = __rhf.game;
    const G = g.props.geyser;
    const p = g.world.place('springs');
    const r = __view(G.x - 26, G.z + 30, G.x, G.y + 6, G.z);
    g.areas.cycle = 'rumble';
    g.areas.t = 0.1;
    return 'springs: ' + r + ', geyser at ' + G.x.toFixed(0) + ',' + G.z.toFixed(0) + ', place ' + p.x.toFixed(0) + ',' + p.z.toFixed(0) + ', steam emitters ' + g.areas.steam.length + ', mud pots ' + g.areas.mud.length;
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.areas.cycle === 'blow' && g.areas.t < 7.5, 120000);
    return 'geyser ' + g.areas.cycle + ' ' + g.areas.t.toFixed(1);
  })()

(() => {
    const g = __rhf.game;
    const hp = g.world.lakeById.hotpool;
    const it = g.props.interactions.find((i) => i.id === 'soak');
    const r = __view(it.x + (it.x - hp.x) * 0.15, it.z + (it.z - hp.z) * 0.15, hp.x, hp.level, hp.z);
    return 'hot pool: ' + r;
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.interaction && g.interaction.label === 'SOAK', 60000);
    return 'pill ' + (g.interaction ? g.interaction.label : 'none');
  })()

(async () => {
    const g = __rhf.game;
    const t0 = g.env.time;
    g.player.health = 40;
    await __until(() => g.state.challenges.soak || Math.abs(g.env.time - t0) > 0.5, 60000);
    await new Promise((r) => setTimeout(r, 2500));
    return 'after SOAK: time ' + t0.toFixed(2) + ' > ' + g.env.time.toFixed(2) + ', health ' + Math.round(g.player.health) + ', soak challenge ' + !!g.state.challenges.soak;
  })()

(() => {
    const g = __rhf.game;
    const W = g.world;
    const p = W.river.sample(W.fallsS + 26);
    const t = W.river.sample(W.fallsS);
    const nx = -p.tz;
    const nz = p.tx;
    let x = p.x + nx * (W.riverWidth(W.fallsS + 26) + 4);
    let z = p.z + nz * (W.riverWidth(W.fallsS + 26) + 4);
    const r = __view(x, z, t.x, W.riverLevel(W.fallsS) - 5, t.z);
    g.env.setTime(10.5);
    return 'falls: ' + r;
  })()

(() => {
    const g = __rhf.game;
    const L = g.world.place('landing');
    const r = __view(L.x, L.z, L.x - 900, 260, L.z - 900);
    return 'mountains: ' + r;
  })()

(() => {
    const g = __rhf.game;
    const pk = g.props.layout.parking.flats;
    const side = pk.side;
    const perp = { x: -side.z, z: side.x };
    const mx = pk.x + side.x * 6 + perp.x * 7;
    const mz = pk.z + side.z * 6 + perp.z * 7;
    const r = __view(mx - side.x * 9 - perp.x * 3, mz - side.z * 9 - perp.z * 3, mx, g.world.heightAt(mx, mz) + 4, mz);
    g.env.setTime(12);
    return 'flats: ' + r;
  })()

(() => {
    const g = __rhf.game;
    const p = g.world.place('flats');
    const pk = g.props.layout.parking.flats;
    const r = __view(pk.x + pk.side.x * 3, pk.z + pk.side.z * 3, p.x, p.y, p.z);
    return 'boardwalk: ' + r + ', mosquitoes ' + g.insects.layers.mosquito.material.uniforms.uActive.value.toFixed(2);
  })()

(() => {
    const g = __rhf.game;
    const p = g.world.place('wreck');
    const w = p.wreckAt;
    const g2 = g.world.coastGradient(p.x, p.z);
    const r = __view(p.x + g2.x * 8 + g2.z * 14, p.z + g2.z * 8 - g2.x * 14, w.x, 3, w.z);
    return 'wreck: ' + r + ', ship at ' + w.x.toFixed(0) + ',' + w.z.toFixed(0) + ', deck top ' + g.props.wreckDeck.top.toFixed(2);
  })()

(async () => {
    const g = __rhf.game;
    const D = g.props.wreckDeck;
    // walk up the gangplank: place at its foot and hold forward
    const p = g.world.place('wreck');
    const w = p.wreckAt;
    const bx = w.x + Math.sin(w.yaw) * 10;
    const bz = w.z + Math.cos(w.yaw) * 10;
    __view(p.x, p.z, bx, D.top + 1.5, bz);
    const k = g.input;
    k.keys.add('KeyW');
    const t0 = g.time;
    await __until(() => g.player.onDeck && Math.hypot(g.player.pos.x - D.x, g.player.pos.z - D.z) < 9 || g.time - t0 > 14, 200000);
    k.keys.delete('KeyW');
    const P = g.player;
    return 'after walking up: on a deck ' + P.onDeck + ', y ' + P.pos.y.toFixed(2) + ' (deck ' + D.top.toFixed(2) + '), ' + Math.hypot(P.pos.x - D.x, P.pos.z - D.z).toFixed(1) + ' m from the middle, flag ' + !!g.state.flags.deck;
  })()

(() => {
    const g = __rhf.game;
    const p = g.world.place('wreck');
    const P = g.player;
    P.yaw = Math.atan2(-(p.waterX - P.pos.x), -(p.waterZ - P.pos.z));
    P.pitch = -0.15;
    return 'looking out to sea';
  })()
